export const source="project KingCajunScheduledOrders\n\nactor OrderBot\n  @type system\n  @boundary external\n  @affiliation internal\n  @access none\n\nactor Dispatcher\n  @type person\n  @affiliation internal\n  @access authenticated\n  @signup invite\n\nobject Booking\n  channel: delivery | pickup\n  status: proposed | reserved @final\n  noticeMinutes: int\n  serviceOpen: bool\n  pinConfirmed: bool\n  nightlyCount: int\n  groupCount: int\n  driverFree: bool\n\nobject Trip\n  status: planned | out | returned @final\n  driverAvailable: bool\n  departureDue: bool\n  ordersReady: bool\n\nstory Scheduling\n  OrderBot creates Booking\n    sets Booking.status to \"proposed\"\n  OrderBot creates Trip\n    sets Trip.status to \"planned\"\n  OrderBot reserves Booking\n    requires Booking.status is \"proposed\"\n    requires Booking.noticeMinutes is at least 60\n    requires Booking.serviceOpen is true\n    requires Booking.channel is \"pickup\" or Booking.pinConfirmed is true\n    requires Booking.channel is \"pickup\" or Booking.nightlyCount is at most 12\n    requires Booking.channel is \"pickup\" or Booking.groupCount is at most 3\n    requires Booking.channel is \"pickup\" or Booking.driverFree is true\n    sets Booking.status to \"reserved\"\n\nstory Dispatch\n  Dispatcher dispatches Trip\n    requires Trip.status is \"planned\"\n    requires Trip.driverAvailable is true\n    requires Trip.departureDue is true\n    requires Trip.ordersReady is true\n    sets Trip.status to \"out\"\n  Dispatcher returns Trip\n    requires Trip.status is \"out\"\n    sets Trip.status to \"returned\"\n";
